// === Tab: attractor_DeJong_on_white ===
// let 2D strange attractor using the let formula.
// let using the 'log of the density of hits' approach,
// see: 'The Fractal Flame Algorithm' - Draves/Reckase.
// attractor, DeJong, log(), PImage, sin(), cos()
// does not render quickly
let tractor;
let runNum ;

function setup() {
  createCanvas(650, 650);
  background(255);
  tractor = new Attractor();
  runNum = 0;
}

function draw() {
  if (runNum < 10) { // stop sketch looping forever
    tractor.calcPoints(); // do attractor sums
    tractor.drawToImg(); // draw in memory
    image(tractor.img, 0, 0, width, height); // flip to monitor
    runNum++;
  }
}

class Attractor {
  img;
  x, y, a, b, c, d, xNew, yNew, num;
  logMaxHits, imgX, imgY;
  scale, maxHits, layers, pnts;
  newCol, oldCol;
  imgW = 750; 
  imgH = 750;
  int[][] hits = new Array(imgW)[imgH];

  constructor() {
    layers = 10;
    pnts = 147000; // numPnts == pnts * layers * runNum
    scale =  175;
    maxHits = 0; 

    img = createImage(imgW, imgH, RGB);

    for (i = 0; i < imgW; i++) { // init to zero
      for (j = 0; j < imgH; j++) {
        hits[i][j] = 0;
      }
    }

    a = -1.19; // coefficients
    b = 1.8;
    c = 0.71; 
    d = 1.57;
  }

  function calcPoints() {
    x = y = 0;
    for (k = 0; k < layers; k++) {
      for (l = 0; l < pnts; l++) {

        xNew = sin(y*a) - cos(x*b); // tractor calcs
        yNew = sin(x*c) - cos(y*d);

        xNew += random(-0.001, 0.001); // blur code  within feedback loop
        yNew += random(-0.001, 0.001);

        x = xNew; // feedback
        y = yNew;

        // convert to let co-ords and collect hit numbers 
        imgX = xNew * scale + imgW/2;
        imgY = yNew * scale + imgH/2;

        // let doesn't usually  need a bounds check
        //if ((imgX > 0) && (imgX < imgW) && (imgY > 0) && (imgY < imgH) ) {
        hits[int(imgX)][int(imgY)]  += 1;
        if (hits[int(imgX) ][int(imgY)] > maxHits)
          maxHits = hits[int(imgX )][int(imgY)];
      }
      // }
    }
    logMaxHits = log(maxHits);
  }

  function drawToImg() {
    img.loadPixels();
    for (m = 0; m < imgW; m++) {
      for (n = 0; n < imgH; n++) {
        if (hits[m][n] > 0) {
          num = map(log(hits[m][n]), 0, logMaxHits, 0, 250); 
          newCol = color(250-num *.5, 250-num, 230-num*3);
          oldCol = img.pixels[m * imgW + n];
          // using  blend here  from  let Frolich sketch "#2097"
          newCol = blendColor(newCol, oldCol, SOFT_LIGHT);
          // transfer to img screen
          img.pixels[m * imgW + n] = newCol;
          // white everywhere else
        } else img.pixels[m*imgW+n] = color(255);
      }
    }
    img.updatePixels();
  }
}

